"""The commands that run systems and measure, as operations that run as jobs (RFC-032 step 9 P3, step 6): a run and a
sweep of runs (which spend, and a run's id comes from its job, so a stopped one is resumed as a new job), the judge's pass
and the re-score, a smoke, a model's onboarding, a replay's faithfulness and the naming of its exceptions, the preview
of a scorer, and the statistics that read stored runs. Each is a POST on its resource and answers 202 with the job; an
operation that spends takes `max_cost_usd`."""

from __future__ import annotations

from evaluation_harness.ops.registry import Op

OPS = (
    Op("run", "work", "run one arm over a dataset (--dry-run to cost it)",
       "POST", "/systems/{system}/runs", "evaluation_harness.run:body", "",
       locks=(("system:{system}", True), ("dataset:{dataset}", False)), spends=True, resume=("resume", "run_id",), required=("system", "dataset",), inputs={
           "system": {"type": "string", "description": "the system to run: its id (evh system-list)", "x-ref": "system"},
           "dataset": {"type": "string", "description": "the dataset it runs on: its id (evh dataset-list)"},
           "goal": {"type": "string", "description": "the goal this run is measured for (ADR-0002); required from the date data/goals/policy.yaml gives (one line there: required_from: YYYY-MM-DD; the file is yours to create; --scratch excepted)"},
           "round": {"type": "string", "description": "the round of its goal the run belongs to (ADR-0004): needs --goal, on the round's dataset"},
           "labels": {"type": "string", "x-metavar": "SET", "description": "score against this label set of the dataset (SET or DATASET/SET) instead of its gold or silver (RFC-023)"},
           "repeat": {"type": "integer", "default": 1, "description": "run N times to measure the arm's spread"},
           "purpose": {"type": "string", "enum": ["run", "repeat", "pair", "retime"], "default": "run", "description": "what the run is for (RFC-032): run (default), repeat (another measurement of a system's run: needs --of, and is read in that run's arm when it is the same measurement, else under `repeats`), retime (the same on another machine), pair (a run for a paired test); a retime and a pair are read under labels of their own"},
           "of": {"type": "string", "x-metavar": "RUN_ID", "description": "the run a re-run (--purpose repeat, retime, pair) re-does: a run of the same system and dataset; required by --purpose repeat"},
           "scratch": {"type": "boolean", "description": "a throwaway pass: written under .build/scratch/runs, where nothing that reads runs looks"},
           "run_id": {"type": "string", "description": "the id the run is written under (default: the job's, <system>_<job id>; on the command line <system>_<timestamp>)"},
           "items": {"type": "string", "format": "path", "x-metavar": "FILE", "description": "run only these item ids (one per line) of the dataset: a study's confirmation leaves out the items its study saw (RFC-029). The fingerprint's items are then these; a test set's looks are still the whole set's. A subset is other data than the whole dataset: a --purpose repeat of a run joins that run's arm only if the run ran exactly these items, else it is read under `repeats` (its line says so, and --dry-run too)", "x-file": "upload"},
           "dry_run": {"type": "boolean", "description": "cost and shape the sweep WITHOUT calling anything"},
           "resume": {"type": "string", "x-metavar": "RUN_ID", "description": "the run to continue: the outputs it already produced are reused, only what is missing is paid for"},
           "recall_failed": {"type": "boolean", "description": "with --resume, on a call-once arm (its adapter declares CALL_ONCE, RFC-038): call again the items the run called once and did not finish (a failed item, or one the process died in), once each; their side effects happen again, and the run records which items it recalled"},
           "unfaithful": {"type": "boolean", "description": "a replay (RFC-030) whose faithfulness record does not agree with production is scored anyway, by a person (an agent is refused); the run and every page showing it say so"},
       }),
    Op("sweep", "work", "run several arms, then the leaderboard",
       "POST", "/datasets/{dataset}/sweeps", "evaluation_harness.sweep:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:sweep_locks", spends=True, required=("systems", "dataset",), inputs={
           "systems": {"type": "array", "items": {"type": "string"}, "x-nargs": "+", "description": "the systems to run: their ids (evh system-list)", "x-ref": "system"},
           "dataset": {"type": "string", "description": "the one dataset they all run on"},
           "goal": {"type": "string", "description": "the goal the runs are measured for"},
           "round": {"type": "string", "description": "the round of its goal the runs belong to (needs --goal)"},
           "repeat": {"type": "integer", "default": 1, "description": "run each arm N times"},
           "dry_run": {"type": "boolean", "description": "cost it without calling anything"},
           "scratch": {"type": "boolean", "description": "a throwaway sweep: each arm written under .build/scratch/runs (evh run --scratch), no leaderboard"},
           "sort": {"type": "string", "description": "leaderboard metric"},
       }),
    Op("judge-score", "work", "re-measure frozen outputs with a validated LLM judge (--dry-run first)",
       "POST", "/scorers/{scorer}/judge", "evaluation_harness.judge_score:body", "",
       locks=(("dataset:{dataset_id}", True),), spends=True, required=("dataset_id", "scorer",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset whose arms' frozen outputs are judged"},
           "scorer": {"type": "string", "description": "scorer id (data/scorers/<id>.yaml)"},
           "dry_run": {"type": "boolean", "description": "build the judging set; print calls, tokens and estimated cost; call nothing"},
           "unvalidated": {"type": "boolean", "description": "run a scorer the gate refuses; every number is labelled 'unvalidated judge'"},
           "no_calls": {"type": "boolean", "description": "project from stored verdicts only; never call a judge ($0)"},
           "retry_unparsed": {"type": "boolean", "description": "call again for stored verdicts whose reply did not parse"},
           "match": {"type": "string", "description": "arm set: system_id substring (default: the scorer's arms_match, else every arm on the dataset)"},
           "arms": {"type": "string", "description": "comma-separated system_ids or substrings: judge only these arms (a subset is its own judging set id)"},
       }),
    Op("rescore", "work", "re-score stored outputs, a round's or a dataset's, for $0",
       "POST", "/runs/rescore", "evaluation_harness.rescore:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:rescore_locks", required=(), inputs={
           "dataset_id": {"type": "string", "description": "the dataset whose runs to re-score (or --goal and --round)"},
           "match": {"type": "string", "description": "only runs whose system_id contains this substring"},
           "label": {"type": "string", "description": "the label the scores are read under (default: 'rescored <8 characters of the scorer>'; 'silver' with --reference-id silver/...; 'labels-<dataset>-<set>' with --labels)"},
           "reference_id": {"type": "string", "description": "score against THIS reference set (e.g. gold/my_v1) instead of the one each run recorded -- for when gold arrives after the runs"},
           "labels": {"type": "string", "x-metavar": "SET", "description": "score against a label set of the dataset (SET or DATASET/SET), without promoting it; read under its own label (labels-<dataset>-<set>), never where a goal reads a re-score (RFC-023)"},
           "goal": {"type": "string", "description": "with --round: re-score that round's arms"},
           "round": {"type": "string", "description": "the round whose arms (its own and those it carried) to re-score"},
           "why": {"type": "string", "default": "", "description": "with --round: why the scoring changed, recorded on the round"},
           "unfaithful": {"type": "boolean", "description": "re-score a replay (RFC-030) whose faithfulness record does not agree with production, as a person (an agent is refused); the record says so"},
       }),
    Op("arm-smoke", "work", "smoke an arm on a few items before its full run: checks, projection, flags",
       "POST", "/systems/{system}/smoke", "evaluation_harness.arm_smoke:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:model_locks", spends=True, required=("system", "dataset",), inputs={
           "system": {"type": "string", "description": "the system to smoke: its id (evh system-list)", "x-ref": "system"},
           "dataset": {"type": "string", "description": "the dataset whose first items it runs"},
           "goal": {"type": "string", "description": "the goal its full run is for"},
           "round": {"type": "string", "description": "the round its full run is in: the smoke spends on the round (needs --goal)"},
           "items": {"type": "integer", "default": 3, "description": "how many of the dataset's first items (default 3)"},
           "no_record": {"type": "boolean", "description": "do not write the report into the model record"},
           "replies": {"type": "boolean", "description": "print each reply whole (default: its first 300 characters)"},
       }),
    Op("model-onboard", "work", "onboard a model once: probe a deployment, write what was found into its record",
       "POST", "/models/{model}/onboard", "evaluation_harness.model_onboard:body", "",
       locks=(("model:{model_id}", True),), locks_fn="evaluation_harness.ops.locks:model_locks", spends=True, parts={"model": "model_id"}, required=("model_id",), inputs={
           "model_id": {"type": "string", "description": "the model's id (data/models/<id>.yaml)"},
           "deployment": {"type": "string", "description": "the deployment to probe and write: an `id` in the record's deployments"},
           "system": {"type": "string", "description": "a system that runs the model (an ML model or a baseline): its id", "x-ref": "system"},
           "dataset": {"type": "string", "description": "the dataset whose first items the system runs (with --system)"},
       }),
    Op("faithfulness", "work", "replay a system at the commits production ran and compare it with production's arm, item by item",
       "POST", "/systems/{system}/faithfulness", "evaluation_harness.faithfulness:body", "",
       locks=(), locks_fn="evaluation_harness.ops.locks:model_locks", spends=True, required=("system", "dataset", "production",), inputs={
           "system": {"type": "string", "description": "the replay system (replay:, model_record: a code record): its id", "x-ref": "system"},
           "dataset": {"type": "string", "description": "the dataset it replays, production's arm's"},
           "production": {"type": "string", "x-metavar": "RUN_ID", "description": "production's arm: a run on the same dataset holding what production did (a recorded arm)"},
           "dry_run": {"type": "boolean", "description": "the plan (items, commits) without calling anything"},
       }),
    Op("faithfulness-name", "decision", "name a replay's disagreement whose cause is outside the system (a person's decision)",
       "POST", "/models/{model}/faithfulness/name", "evaluation_harness.faithfulness_name:body", "",
       locks=(("model:{model}", True),), why="cause", required=("model", "item", "cause",), inputs={
           "model": {"type": "string", "description": "the code record (data/models/<id>.yaml, kind: code)"},
           "n": {"type": "integer", "description": "the faithfulness record's number (default: the newest)"},
           "item": {"type": "string", "description": "the item whose disagreement is named"},
           "cause": {"type": "string", "description": "what outside the system caused it, in words"},
       }),
    Op("score-preview", "work", "what the scorer in this tree would move in a goal's decision; writes nothing",
       "POST", "/goals/{goal}/score-preview", "evaluation_harness.score_preview:body", "",
       locks=(), required=("goal",), inputs={
           "goal": {"type": "string", "description": "the goal whose decision is previewed"},
           "round": {"type": "string", "description": "only this round's arms (its own and those it carried)"},
       }),
    Op("silver-calibrate", "work", "how far silver reference sets drift from gold",
       "POST", "/datasets/{dataset}/silver-calibration", "evaluation_harness.silver_calibrate:body", "",
       locks=(), parts={"dataset": "dataset_id"}, required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset"},
           "ref_match": {"type": "string", "description": "substring of the system id: the runs whose outputs are used AS the silver references, e.g. _v1 (with --arm-match, two sets of runs that share none: two versions, or repeats)"},
           "arm_match": {"type": "string", "description": "substring of the system id: the runs scored against those references, e.g. _v2"},
           "reference_id": {"type": "string", "description": "trusted reference dir under data/references (default: the one the runs recorded)"},
           "metric": {"type": "string", "description": "default: the adapter's PRIMARY_METRIC"},
           "group_by": {"type": "string", "default": "family", "description": "params key for the sibling-bias report; '' to skip"},
       }),
    Op("bootstrap-test", "work", "bootstrap intervals for corpus-level metrics",
       "POST", "/datasets/{dataset}/bootstrap-tests", "evaluation_harness.bootstrap_test:body", "",
       locks=(), parts={"dataset": "dataset_id"}, tool_hidden=("items",), required=("dataset_id", "a", "against",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset"},
           "a": {"type": "string", "description": "system_id of the arm under test"},
           "against": {"type": "string", "description": "substring selecting the opponent family, declared in advance"},
           "metric": {"type": "string", "enum": ["accuracy", "macro_f1"], "default": "macro_f1", "description": ""},
           "draws": {"type": "integer", "default": 5000, "description": ""},
           "alpha": {"type": "number", "default": 0.05, "description": ""},
           "seed": {"type": "integer", "default": 20260927, "description": ""},
           "exclude_dataset": {"type": "string", "description": "drop items this dataset also contains"},
           "items": {"type": "string", "format": "path", "description": "file of item_ids; restrict to exactly these"},
           "cluster": {"type": "string", "x-metavar": "FIELD", "description": "an item field whose items are not independent: resample whole clusters (values of it), not items"},
       }),
    Op("holdout", "work", "tune on a pilot slice, confirm on the rest",
       "POST", "/datasets/{dataset}/holdout", "evaluation_harness.holdout_significance:body", "",
       locks=(), parts={"dataset": "dataset_id"}, required=("dataset_id",), inputs={
           "dataset_id": {"type": "string", "description": "the dataset"},
           "exclude_dataset": {"type": "string", "description": "drop every item this dataset also contains"},
           "metric": {"type": "string", "description": "default: the metric that decides on the dataset: its goal's measure, else the runs' primary metric"},
           "match": {"type": "string", "description": "only system_ids containing this substring"},
           "asc": {"type": "boolean", "description": "lower is better (default: inferred)"},
           "desc": {"type": "boolean", "description": "higher is better, whatever the runs declare"},
       }),
)  # fmt: skip
